/** The latest posts of MediaList as rows: a dot, the title, the date and reading time. */
import { For, type JSX } from "solid-js";
import { Group, Inline, Stack, Text } from "../compose";
import { MenuEntry } from "../components/menu-entry";
import { tpl } from "../utils";
import type { MediaExtras, MediaListLabels } from "../blocks/media-list.types";

export type MediaPostsProps = {
  extras: MediaExtras;
  labels: MediaListLabels;
};

export function MediaPosts({ extras, labels }: MediaPostsProps) {
  return (
    <Stack gap="4" align="stretch" data-slot="media-posts">
      <Text size="sm" weight="semibold">
        {labels.list}
      </Text>
      <For each={extras.posts ?? []}>{(p, iOf) => { const i = iOf(); return (
        <>
          {(i < 3) ? (
            <Group gap="4" align="start" data-slot="media-post">
              <Inline class="mt-2 size-2 shrink-0 rounded-full bg-primary" />
              <Stack gap="0">
                <MenuEntry href={p.href} class="text-sm font-medium" size="sm">
                  {p.title}
                </MenuEntry>
                <Text size="xs" class="text-muted-foreground">
                  {tpl("{0} · {1}", p.date, tpl(labels.minutes, p.minutes))}
                </Text>
              </Stack>
            </Group>
          ) : null}
        </>
      ); }}</For>
    </Stack>
  );
}
